#!/usr/bin/env bash
# Build Legatum as a Tauri v2 iOS app for the iOS Simulator (Apple Silicon), and optionally run it:
#   1. the WASM engine (crates/wasm -> app/src/wasm-pkg)
#   2. the Xcode project (app/src-tauri/gen/apple, generated by `tauri ios init`; git-ignored)
#   3. the web UI plus the Rust shell for aarch64-apple-ios-sim, bundled as Legatum.app
# Usage: scripts/build-ios-sim.sh [--release] [--run ["Simulator name"]]
#   --run boots the named simulator (default "iPad Pro 11-inch (M4)"), installs and launches the app.
# Needs: Rust (cargo + wasm-pack), Node/npm, Xcode with an iOS Simulator runtime. The first run of
# `tauri ios init` adds the iOS rustup targets and installs xcodegen and libimobiledevice via Homebrew.
# Simulator builds need no signing team.
set -euo pipefail
cd "$(dirname "$0")/.."
[ -f "$HOME/.cargo/env" ] && . "$HOME/.cargo/env"

profile=(--debug)
run=0
device="iPad Pro 11-inch (M4)"
while [ $# -gt 0 ]; do
  case "$1" in
    --release) profile=() ;;
    --run)
      run=1
      if [ $# -gt 1 ] && [ "${2#--}" = "$2" ]; then device="$2"; shift; fi
      ;;
    *) echo "unknown argument: $1" >&2; exit 1 ;;
  esac
  shift
done

for tool in cargo rustup wasm-pack npm xcrun xcodebuild; do
  command -v "$tool" >/dev/null || { echo "missing $tool" >&2; exit 1; }
done

scripts/build-wasm.sh

cd app
[ -d node_modules ] || npm ci
[ -d src-tauri/gen/apple ] || npx tauri ios init --ci
# Runs beforeBuildCommand (npm run build), merges src-tauri/tauri.ios.conf.json and Info.ios.plist.
npx tauri ios build ${profile[@]+"${profile[@]}"} --target aarch64-sim --ci

app_path="$PWD/src-tauri/gen/apple/build/arm64-sim/Legatum.app"
[ -d "$app_path" ] || { echo "build finished but $app_path is missing" >&2; exit 1; }
echo
echo "Built: $app_path ($(du -sh "$app_path" | cut -f1))"

if [ "$run" = 0 ]; then
  echo "Run:   scripts/build-ios-sim.sh --run [\"Simulator name\"]"
  exit 0
fi

# Pick the named simulator: a booted one first, else the one on the newest iOS runtime.
udid=$(xcrun simctl list devices available -j | DEVICE="$device" python3 -c '
import json, os, sys
name = os.environ["DEVICE"]
found = [(d["state"] == "Booted", rt, d["udid"])
         for rt, ds in json.load(sys.stdin)["devices"].items() if ".iOS-" in rt
         for d in ds if d["name"] == name]
print(max(found)[2] if found else "")')
[ -n "$udid" ] || { echo "no available simulator named \"$device\" (xcrun simctl list devices)" >&2; exit 1; }

xcrun simctl boot "$udid" 2>/dev/null || true
xcrun simctl bootstatus "$udid" -b >/dev/null
open -a Simulator --args -CurrentDeviceUDID "$udid" || true
xcrun simctl install "$udid" "$app_path"
xcrun simctl launch --terminate-running-process "$udid" com.legatum.game
echo "Launched on $device ($udid)"
echo "Screenshot: xcrun simctl io $udid screenshot <path>.png"
